  private updateFace(dt: number, time: number): void {
    const e = this.expr;
    const parts = this.parts;

    // Blink timer.
    this.blinkTimer -= dt;
    if (this.blinkT < 0 && this.blinkTimer <= 0) {
      this.blinkT = 0;
      this.blinkTimer = 2 + Math.random() * 3;
    }
    let blink = 1;
    if (this.blinkT >= 0) {
      this.blinkT += dt / 0.16;
      if (this.blinkT >= 1) this.blinkT = -1;
