      blush.visible = e.blush > 0.02;
    });
    parts.blushMaterial.opacity = Math.min(0.75, e.blush * 0.75);

    parts.spots.forEach((spot, i) => {
      const show = this.stage !== "Baby";
      spot.visible = show || spot.scale.x > 0.01;
      const target = show ? 1 : 0.0001;
      const base = spot.userData.base ?? (spot.userData.base = spot.scale.clone());
      const s = i < 9 ? target : target;
      spot.scale.lerp(base.clone().multiplyScalar(s), 0.2);
      if (spot.scale.x < 0.01) spot.visible = false;
    });

    parts.dirt.forEach((mark, i) => {
      mark.visible = i < this.dirtCount;
    });

    parts.horns.forEach((horn) => {
      const target = this.stage === "Baby" ? 0.0001 : 1;
      horn.scale.setScalar(horn.scale.x + (target - horn.scale.x) * 0.15);
    });
  }

  private updateAppendages(time: number): void {
    const parts = this.parts;
    const wagAmp = this.happiness > 60 ? 0.6 : 0.2;
    parts.tail.rotation.y = Math.sin(time * (this.happiness > 60 ? 9 : 3)) * wagAmp;
    parts.ears.forEach((ear, i) => {
