    const k = 1 - Math.exp(-dt * 8);
    this.root.scale.setScalar(this.root.scale.x + (this.stageScale - this.root.scale.x) * k);
    this.parts.body.scale.set(1 * this.belly, 0.92 * (1 + (this.belly - 1) * 0.25), 0.95 * this.belly);

    // Face the walk direction.
    const yawTarget = this.hop ? this.facingTarget : 0;
    this.parts.pivot.rotation.y += (yawTarget - this.parts.pivot.rotation.y) * Math.min(1, dt * 6);
    if (this.shakeTimer > 0) {
      this.shakeTimer = Math.max(0, this.shakeTimer - dt);
      const amp = Math.min(1, this.shakeTimer * 2);
      this.parts.pivot.rotation.y += Math.sin(time * 36) * 0.22 * amp * dt * 12;
      this.parts.pivot.rotation.z = Math.sin(time * 36) * 0.04 * amp;
    } else {
      this.parts.pivot.rotation.z *= 1 - Math.min(1, dt * 10);
