      this.blinkT = 0;
      this.blinkTimer = 2 + Math.random() * 3;
    }
    let blink = 1;
    if (this.blinkT >= 0) {
      this.blinkT += dt / 0.16;
      if (this.blinkT >= 1) this.blinkT = -1;
