      1 + squashAmount * 0.5 - breath * 0.5 + sleepSquash * 0.5,
      1 - squashAmount * 0.6 + breath - sleepSquash,
      1 + squashAmount * 0.5 - breath * 0.5 + sleepSquash * 0.5,
    );
