import * as THREE from "three";
import type { Stage } from "../game/state";
import { buildCowdie, type CowdieParts } from "./cowdie-model";

export type Mood = "content" | "happy" | "hungry" | "sad" | "sleep" | "eat" | "yum" | "annoyed";

