  private stage: Stage = "Baby";
  private belly = 1;
  private dirtCount = 0;
  private happiness = 70;
  private asleep = false;

  private squash = 0;
  private squashVel = 0;
  private biteTimer = 0;
  private jumpT = -1;
  private jumpDuration = 0.5;
  private jumpHeight = 0;
