    this.parts = buildCowdie();
    this.root = this.parts.root;
    this.root.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.castShadow = true;
      }
    });
    this.root.scale.setScalar(this.stageScale);
  }

