  bite(): void {
    this.squashVel += 9;
    this.biteTimer = 0.22;
  }

  /** Jump in place. */
  jump(height = 0.5, duration = 0.55): void {
    this.jumpT = 0;
    this.jumpHeight = height;
    this.jumpDuration = duration;
