    }

    // Gaze: follow the target if any, otherwise wander gently.
    if (this.gazeTarget) {
      const local = this.root.worldToLocal(this.tmpV.copy(this.gazeTarget));
      this.gazeGoal.set(
        Math.max(-1, Math.min(1, local.x * 0.5)),
