    this.stage = vitals.stage;
    this.stageScale = STAGE_SCALE[vitals.stage];
    this.belly = 1 + (vitals.fullness - 50) / 350;
    this.dirtCount = Math.round(Math.min(1, Math.max(0, (100 - vitals.hygiene) / 70)) * this.parts.dirt.length);
