        transparent: true,
        opacity: 0.55,
        depthWrite: false,
      }),
      sparkle: new THREE.MeshStandardMaterial({
        color: 0xfff3a3,
        emissive: 0xffd64d,
        emissiveIntensity: 1.2,
        roughness: 0.3,
      }),
    };
  }

  emit(kind: ParticleKind, origin: THREE.Vector3, options: EmitOptions = {}): void {
