args.streamContent:
:root {
  --ink: #3a2f3b;
  --ink-soft: #7a6a78;
  --card: rgba(255, 255, 255, 0.78);
  --accent: #ff7aa2;
  --accent-2: #ffb86b;
  --good: #7bd389;
  --warn: #ff8f6b;
  --radius: 18px;
  font-family: ui-rounded, "SF Pro Rounded", "Avenir Next", system-ui, -apple-system, sans-serif;
  color: var(--ink);
  color-scheme: light;
  -webkit-font-smoothing: antialiased;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #bfe7ff;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 3px solid rgba(255, 122, 162, 0.7);
  outline-offset: 2px;
}

#app {
  position: fixed;
  inset: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  user-select: none;
  -webkit-user-select: none;
}

/* ---------- Header ---------- */

.hud-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px 6px;
  position: relative;
  z-index: 3;
}

.brand h1 {
  margin: 0;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.01em;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
  white-space: nowrap;
}

.pet-card {
  flex: 1;
  max-width: 300px;
  padding: 8px 14px 10px;
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
}

.pet-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  font-weight: 800;
}

.pet-name {
  font-size: 17px;
}

.pet-stage,
.pet-level {
  font-size: 11px;
  font-weight: 800;
  padding: 3px 8px;
  border-radius: 999px;
  background: #ffe3ee;
  color: #b4467a;
}

.pet-level {
  margin-left: auto;
  background: #fff1cf;
  color: #9a6510;
}

.xp-track {
  margin-top: 8px;
  height: 7px;
  border-radius: 999px;
  background: rgba(120, 90, 140, 0.14);
  overflow: hidden;
}

.xp-fill {
  height: 100%;
  width: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--accent-2), var(--accent));
  transform-origin: left center;
  transform: scaleX(0);
  transition: transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.top-tools {
  display: flex;
  gap: 8px;
}

.icon-btn {
  width: 40px;
  height: 40px;
  border: none;
  border-radius: 14px;
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
  font-size: 18px;
  line-height: 1;
}

.icon-btn:hover {
  transform: translateY(-1px);
}

/* ---------- Stage ---------- */

.stage {
  position: relative;
  min-height: 0;
  overflow: hidden;
  background: linear-gradient(180deg, #8fd3ff 0%, #c9ecff 45%, #fff3d6 100%);
  transition: background 1.2s ease;
}

.stage.night {
  background: linear-gradient(180deg, #1c2050 0%, #35407a 55%, #7a6fa8 100%);
}

.stage.asleep::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(20, 16, 50, 0.32);
  pointer-events: none;
  animation: fade-in 1.2s ease both;
}

.stage.feed-target {
  box-shadow: inset 0 0 90px rgba(255, 214, 120, 0.7);
}

.stage.dragging {
  cursor: grabbing;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: manipulation;
  cursor: pointer;
}

.bubble {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 2;
  max-width: 230px;
  padding: 9px 14px;
  border-radius: 18px;
  background: #fff;
  color: var(--ink);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 10px 26px rgba(60, 40, 90, 0.18);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  margin-top: -16px;
}

.bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 3px;
}

.bubble.show {
  opacity: 1;
}

.zzz {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 2;
  display: flex;
  gap: 4px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 2px 6px rgba(20, 16, 60, 0.4);
}

.zzz.show {
  opacity: 1;
}

.zzz span {
  animation: zzz-float 2.4s ease-in-out infinite;
  font-size: 14px;
}

.zzz span:nth-child(2) {
  animation-delay: 0.6s;
  font-size: 18px;
}

.zzz span:nth-child(3) {
  animation-delay: 1.2s;
  font-size: 22px;
}

.float-emoji {
  position: absolute;
  z-index: 3;
  font-size: 26px;
  pointer-events: none;
  transform: translate(-50%, -50%);
  animation: float-up 1.1s ease-out forwards;
}

.hint {
  position: absolute;
  left: 50%;
  bottom: 14px;
  z-index: 2;
  transform: translateX(-50%);
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.8);
  font-size: 13px;
  font-weight: 700;
  color: var(--ink-soft);
  white-space: nowrap;
  pointer-events: none;
  transition: opacity 0.6s ease;
}

.hint.gone {
  opacity: 0;
}

.toast {
  position: fixed;
  top: 84px;
  left: 50%;
  z-index: 10;
  transform: translate(-50%, -8px);
  padding: 10px 16px;
  border-radius: 999px;
  background: #2d2a4a;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 10px 26px rgba(30, 20, 60, 0.3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Meters ---------- */

.meters {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 10px 14px 8px;
  position: relative;
  z-index: 3;
}

.meter {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto;
  align-items: center;
