  .pet-card {
    max-width: none;
  }

  .meter-label {
    font-size: 11px;
  }

  .dock-btn {
    width: 68px;
  }

  .food-blurb {
    display: none;
  }

  .food-tray {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

