import puppeteer from "puppeteer-core";

const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const URL = "http://127.0.0.1:9373/";
const OUT = new URL(".", import.meta.url).pathname;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: true,
  defaultViewport: { width: 1280, height: 820, deviceScaleFactor: 1 },
  args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist", "--no-sandbox"],
});

const page = await browser.newPage();
const errors = [];
page.on("console", (msg) => {
  if (msg.type() === "error" || msg.type() === "warning") errors.push(`[${msg.type()}] ${msg.text()}`);
});
page.on("pageerror", (err) => errors.push(`[pageerror] ${err.message}`));

await page.goto(URL, { waitUntil: "networkidle0" });
await sleep(1500);

const title = await page.title();
const h1 = await page.$eval("h1", (el) => el.textContent);
console.log("TITLE:", JSON.stringify(title));
console.log("H1:", JSON.stringify(h1));

const readMeters = () =>
  page.$$eval(".meter", (els) =>
    Object.fromEntries(els.map((el) => [el.dataset.stat, el.querySelector(".meter-value").textContent])),
  );

console.log("METERS_START:", JSON.stringify(await readMeters()));
await page.screenshot({ path: `${OUT}shot-initial.png` });

// Open tray and tap the apple (click path).
await page.click("#btn-feed");
await sleep(400);
await page.screenshot({ path: `${OUT}shot-tray.png` });
await page.click('.food-card[data-food="apple"]');
await sleep(350);
await page.screenshot({ path: `${OUT}shot-eat-start.png` });
await sleep(700);
await page.screenshot({ path: `${OUT}shot-eat-bite.png` });
await sleep(1800);
console.log("METERS_AFTER_FEED:", JSON.stringify(await readMeters()));
await page.screenshot({ path: `${OUT}shot-after-feed.png` });

const saved = await page.evaluate(() => localStorage.getItem("cowdie:save:v1"));
console.log("SAVE:", saved);

console.log("ERRORS:", JSON.stringify(errors, null, 2));
await browser.close();

