import puppeteer from "puppeteer-core";

const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const APP_URL = "http://127.0.0.1:9373/";
const OUT = new URL(".", import.meta.url).pathname;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const MOUTH = { x: 637, y: 440 };

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: true,
  defaultViewport: { width: 1280, height: 820, deviceScaleFactor: 1 },
  args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist", "--no-sandbox"],
});

const errors = [];
const newPage = async (viewport) => {
  const page = await browser.newPage();
  if (viewport) await page.setViewport(viewport);
  page.on("console", (msg) => {
    if (msg.type() === "error" || msg.type() === "warning") errors.push(`[${msg.type()}] ${msg.text()}`);
  });
  page.on("pageerror", (err) => errors.push(`[pageerror] ${err.message}`));
  return page;
};

const meters = (page) =>
  page.$$eval(".meter", (els) =>
    Object.fromEntries(els.map((el) => [el.dataset.stat, Number(el.querySelector(".meter-value").textContent)])),
  );

const seed = (page, patch) =>
  page.evaluate((patch) => {
    const base = {
      name: "Cowdie",
      fullness: 60,
      happiness: 70,
      energy: 90,
      hygiene: 85,
      xp: 0,
      meals: 0,
      asleep: false,
      savedAt: Date.now(),
    };
    localStorage.setItem("cowdie:save:v1", JSON.stringify({ ...base, ...patch, savedAt: Date.now() }));
  }, patch);

const cardCenter = async (page, food) => {
  const box = await page.$eval(`.food-card[data-food="${food}"]`, (el) => {
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  });
  return box;
};

// 1. Drag apple onto the mouth.
let page = await newPage();
await page.goto(APP_URL, { waitUntil: "load" });
await sleep(1200);
await seed(page, { fullness: 40, xp: 0 });
await page.reload({ waitUntil: "load" });
await sleep(1200);
let before = await meters(page);
await page.click("#btn-feed");
await sleep(300);
const apple = await cardCenter(page, "apple");
await page.mouse.move(apple.x, apple.y);
await page.mouse.down();
for (let i = 1; i <= 14; i++) {
  const t = i / 14;
  await page.mouse.move(apple.x + (MOUTH.x - apple.x) * t, apple.y + (MOUTH.y - apple.y) * t);
  await sleep(16);
}
await sleep(250);
await page.screenshot({ path: `${OUT}v-drag-near.png` });
await page.mouse.up();
await sleep(500);
await page.screenshot({ path: `${OUT}v-drag-eat.png` });
await sleep(2200);
let after = await meters(page);
console.log("DRAG_FEED before/after fullness:", before.fullness, "->", after.fullness, "happy", before.happiness, "->", after.happiness);

// 2. Drop away from the pet: food should not be eaten.
await page.click("#btn-feed");
await sleep(300);
const carrot = await cardCenter(page, "carrot");
before = await meters(page);
await page.mouse.move(carrot.x, carrot.y);
await page.mouse.down();
for (let i = 1; i <= 10; i++) {
  await page.mouse.move(carrot.x + ((200 - carrot.x) * i) / 10, carrot.y + ((120 - carrot.y) * i) / 10);
  await sleep(16);
}
await page.mouse.up();
await sleep(1200);
after = await meters(page);
console.log("MISS_DROP fullness:", before.fullness, "->", after.fullness);
await page.close();

// 3. Refusal when stuffed.
page = await newPage();
await page.goto(APP_URL, { waitUntil: "load" });
await sleep(800);
await seed(page, { fullness: 97, xp: 0 });
await page.reload({ waitUntil: "load" });
await sleep(1000);
before = await meters(page);
await page.click("#btn-feed");
await sleep(250);
await page.click('.food-card[data-food="apple"]');
await sleep(700);
await page.screenshot({ path: `${OUT}v-refuse.png` });
await sleep(1500);
after = await meters(page);
console.log("REFUSE fullness:", before.fullness, "->", after.fullness);
await page.close();

// 4. Sleep, dirty + bath.
page = await newPage();
await page.goto(APP_URL, { waitUntil: "load" });
await sleep(800);
await seed(page, { hygiene: 22, happiness: 60, xp: 110 });
await page.reload({ waitUntil: "load" });
await sleep(1200);
await page.screenshot({ path: `${OUT}v-dirty.png` });
before = await meters(page);
await page.click("#btn-bathe");
await sleep(1100);
await page.screenshot({ path: `${OUT}v-bath.png` });
await sleep(2600);
after = await meters(page);
console.log("BATH hygiene:", before.hygiene, "->", after.hygiene);
await page.click("#btn-sleep");
await sleep(1800);
await page.screenshot({ path: `${OUT}v-sleep.png` });
const asleepClass = await page.$eval("#stage", (el) => el.classList.contains("asleep"));
console.log("SLEEP stage.asleep:", asleepClass);
await page.click("#btn-sleep");
await sleep(600);

// 5. Play fetch.
await page.click("#btn-play");
await sleep(500);
await page.screenshot({ path: `${OUT}v-play.png` });
before = await meters(page);
await sleep(4200);
after = await meters(page);
console.log("PLAY happy:", before.happiness, "->", after.happiness, "energy:", before.energy, "->", after.energy);

// 6. Poke.
await page.mouse.click(640, 380);
await sleep(350);
await page.screenshot({ path: `${OUT}v-poke.png` });
await page.close();

// 7. Mobile viewport.
page = await newPage({ width: 390, height: 844, deviceScaleFactor: 2, isMobile: true, hasTouch: false });
await page.goto(APP_URL, { waitUntil: "load" });
await sleep(1500);
await page.click("#btn-feed");
await sleep(300);
await page.screenshot({ path: `${OUT}v-mobile.png` });
await page.close();

console.log("ERRORS:", JSON.stringify(errors, null, 2));
await browser.close();

