  pupils: THREE.Object3D[];
  eyeRound: THREE.Object3D[];
  eyeArcs: THREE.Mesh[];
  smileArc: THREE.Mesh;
  frownArc: THREE.Mesh;
  openMouth: THREE.Mesh;
  brows: THREE.Mesh[];
  blushes: THREE.Mesh[];
  ears: THREE.Group[];
  horns: THREE.Object3D[];
  spots: THREE.Object3D[];
  dirt: THREE.Object3D[];
  tail: THREE.Group;
  hooves: THREE.Mesh[];
  blushMaterial: THREE.MeshStandardMaterial;
}

