  face.add(openShape);
  const blushes: THREE.Mesh[] = [];
  for (const side of [-1, 1]) {
    const blush = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 10), mat.blush);
    blush.scale.set(0.15, 0.09, 0.02);
