import puppeteer from "puppeteer-core";

const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const APP_URL = "http://127.0.0.1:9373/";
const OUT = new URL(".", import.meta.url).pathname;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: true,
  defaultViewport: { width: 1280, height: 820, deviceScaleFactor: 1 },
  args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist", "--no-sandbox"],
});
const page = await browser.newPage();
const logs = [];
page.on("console", (msg) => logs.push(`[${msg.type()}] ${msg.text()}`));
page.on("pageerror", (err) => logs.push(`[pageerror] ${err.message}`));
await page.goto(APP_URL, { waitUntil: "load" });
await sleep(1200);
await page.click("#btn-feed");
await sleep(300);
const card = await page.$eval('.food-card[data-food="apple"]', (el) => {
  const r = el.getBoundingClientRect();
  return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
});
await page.mouse.move(card.x, card.y);
await page.mouse.down();
for (let i = 1; i <= 20; i++) {
  await page.mouse.move(card.x + ((600 - card.x) * i) / 20, card.y + ((250 - card.y) * i) / 20);
  await sleep(30);
}
await sleep(400);
await page.screenshot({ path: `${OUT}dbg-drag-above.png` });
const stageClass = await page.$eval("#stage", (el) => el.className);
console.log("STAGE_CLASS:", stageClass);
await page.mouse.up();
await browser.close();
console.log(logs.join("\n"));

