:root {
  --ink: #3a2f3b;
  --ink-soft: #7a6a78;
  --card: rgba(255, 255, 255, 0.78);
  --accent: #ff7aa2;
  --accent-2: #ffb86b;
  --good: #7bd389;
  --warn: #ff8f6b;
  --radius: 18px;
  font-family: ui-rounded, "SF Pro Rounded", "Avenir Next", system-ui, -apple-system, sans-serif;
  color: var(--ink);
  color-scheme: light;
  -webkit-font-smoothing: antialiased;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #bfe7ff;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 3px solid rgba(255, 122, 162, 0.7);
  outline-offset: 2px;
}

#app {
  position: fixed;
  inset: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  user-select: none;
  -webkit-user-select: none;
}

/* ---------- Header ---------- */

.hud-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px 6px;
  position: relative;
  z-index: 3;
}

.brand h1 {
  margin: 0;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.01em;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
  white-space: nowrap;
}

.pet-card {
  flex: 1;
  max-width: 300px;
  padding: 8px 14px 10px;
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
}

.pet-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  font-weight: 800;
}

.pet-name {
