}

.icon-btn:hover {
  transform: translateY(-1px);
}

/* ---------- Stage ---------- */

.stage {
  position: relative;
  min-height: 0;
  overflow: hidden;
  background: linear-gradient(180deg, #8fd3ff 0%, #c9ecff 45%, #fff3d6 100%);
  transition: background 1.2s ease;
}

.stage.night {
  background: linear-gradient(180deg, #1c2050 0%, #35407a 55%, #7a6fa8 100%);
}

.stage.asleep::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(20, 16, 50, 0.32);
  pointer-events: none;
  animation: fade-in 1.2s ease both;
}

.stage.feed-target {
  box-shadow: inset 0 0 90px rgba(255, 214, 120, 0.7);
}

.stage.dragging {
  cursor: grabbing;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: manipulation;
  cursor: pointer;
}

.bubble {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 2;
  max-width: 230px;
  padding: 9px 14px;
  border-radius: 18px;
  background: #fff;
  color: var(--ink);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 10px 26px rgba(60, 40, 90, 0.18);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  margin-top: -16px;
}

.bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 3px;
}

.bubble.show {
  opacity: 1;
}

.zzz {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 2;
  display: flex;
  gap: 4px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 2px 6px rgba(20, 16, 60, 0.4);
}

.zzz.show {
  opacity: 1;
}

.zzz span {
  animation: zzz-float 2.4s ease-in-out infinite;
  font-size: 14px;
}

.zzz span:nth-child(2) {
  animation-delay: 0.6s;
  font-size: 18px;
}

.zzz span:nth-child(3) {
  animation-delay: 1.2s;
  font-size: 22px;
}

.float-emoji {
  position: absolute;
  z-index: 3;
  font-size: 26px;
  pointer-events: none;
  transform: translate(-50%, -50%);
  animation: float-up 1.1s ease-out forwards;
}

.hint {
  position: absolute;
  left: 50%;
  bottom: 14px;
  z-index: 2;
  transform: translateX(-50%);
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.8);
  font-size: 13px;
  font-weight: 700;
  color: var(--ink-soft);
  white-space: nowrap;
  pointer-events: none;
  transition: opacity 0.6s ease;
}

.hint.gone {
  opacity: 0;
}

.toast {
  position: fixed;
  top: 84px;
  left: 50%;
  z-index: 10;
  transform: translate(-50%, -8px);
  padding: 10px 16px;
  border-radius: 999px;
  background: #2d2a4a;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 10px 26px rgba(30, 20, 60, 0.3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Meters ---------- */

.meters {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 10px 14px 8px;
  position: relative;
  z-index: 3;
}

.meter {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 6px;
  row-gap: 4px;
  padding: 8px 10px;
  border-radius: 16px;
  background: var(--card);
