}

.meter-icon {
  font-size: 14px;
  line-height: 1;
}

.meter-label {
  font-size: 12px;
  font-weight: 800;
  color: var(--ink-soft);
  white-space: nowrap;
}

.meter-value {
  grid-column: 2;
  justify-self: end;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
  margin-top: -2px;
}

.meter-track {
  grid-column: 1 / -1;
  height: 8px;
  border-radius: 999px;
  background: rgba(120, 90, 140, 0.14);
  overflow: hidden;
}

.meter-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffd166, #ff8fb1);
  transform-origin: left center;
  transform: scaleX(0.5);
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.3s ease;
}

.meter[data-stat="energy"] .meter-fill {
  background: linear-gradient(90deg, #9ee8ff, #7aa8ff);
}

.meter[data-stat="hygiene"] .meter-fill {
  background: linear-gradient(90deg, #b8f2d0, #6fd3a6);
}

.meter[data-low="true"] .meter-fill {
  background: linear-gradient(90deg, #ffb199, #ff6f7c);
  animation: pulse 1.2s ease-in-out infinite;
}

/* ---------- Dock ---------- */

.dock {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 4px 12px 16px;
}

.dock-row {
  display: flex;
  gap: 10px;
  justify-content: center;
}

.dock-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  width: 78px;
  padding: 9px 6px 8px;
  border: none;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 8px 20px rgba(80, 60, 120, 0.14);
  font-size: 12px;
  font-weight: 800;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.dock-btn:hover {
  transform: translateY(-2px);
}

.dock-btn:active {
  transform: scale(0.95);
}

.dock-btn.active {
  background: #fff4f8;
  box-shadow: 0 0 0 3px var(--accent), 0 8px 20px rgba(80, 60, 120, 0.14);
}

.dock-emoji {
