  border-radius: 22px;
  background: var(--card);
  box-shadow: 0 12px 30px rgba(80, 60, 120, 0.18);
  animation: rise 0.25s ease both;
}

.food-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 8px 4px 7px;
  border: 2px solid transparent;
  border-radius: 16px;
  background: #fff;
  cursor: grab;
  touch-action: none;
  transition: transform 0.15s ease, border-color 0.2s ease;
}

.food-card:hover {
  transform: translateY(-2px);
  border-color: var(--food);
}

.food-card:active {
  cursor: grabbing;
}

.food-card.locked {
  cursor: not-allowed;
  opacity: 0.55;
  filter: grayscale(0.7);
}

.food-emoji {
  font-size: 28px;
  line-height: 1.1;
}

.food-name {
  font-size: 12px;
  font-weight: 800;
}

.food-blurb {
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-soft);
  text-align: center;
  line-height: 1.2;
}

/* ---------- Motion ---------- */

@keyframes float-up {
  0% {
    opacity: 0;
    transform: translate(-50%, -30%) scale(0.6);
  }
  20% {
    opacity: 1;
    transform: translate(-50%, -60%) scale(1.1);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--drift, 0px)), -220%) scale(0.9);
  }
}

@keyframes zzz-float {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.6;
  }
  50% {
    transform: translateY(-8px);
    opacity: 1;
  }
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* ---------- Small screens ---------- */

@media (max-width: 520px) {
  .hud-top {
    padding: 10px 10px 4px;
    gap: 8px;
  }

  .brand h1 {
    font-size: 11px;
    padding: 6px 9px;
  }

  .pet-card {
    flex: 1;
    min-width: 0;
    max-width: none;
    padding: 6px 10px 8px;
  }

  .pet-name {
    font-size: 15px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .pet-stage,
  .pet-level {
    font-size: 10px;
  }

  .icon-btn {
    width: 36px;
    height: 36px;
  }

  .meters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 8px 10px 6px;
  }

  .hint {
    max-width: calc(100% - 28px);
    white-space: normal;
    text-align: center;
  }

  .dock {
    padding: 4px 8px 14px;
  }

  .food-tray {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: 100%;
    padding: 8px;
  }

  .food-blurb {
    display: none;
  }

  .dock-btn {
    width: 68px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

