:root {
  --ink: #3a2f3b;
  --ink-soft: #7a6a78;
  --card: rgba(255, 255, 255, 0.78);
  --accent: #ff7aa2;
  --accent-2: #ffb86b;
  --good: #7bd389;
  --warn: #ff8f6b;
  --radius: 18px;
  font-family: ui-rounded, "SF Pro Rounded", "Avenir Next", system-ui, -apple-system, sans-serif;
  color: var(--ink);
  color-scheme: light;
  -webkit-font-smoothing: antialiased;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #bfe7ff;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 3px solid rgba(255, 122, 162, 0.7);
  outline-offset: 2px;
}

#app {
  position: fixed;
  inset: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  user-select: none;
  -webkit-user-select: none;
}

/* ---------- Header ---------- */

.hud-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px 6px;
  position: relative;
  z-index: 3;
}

.brand h1 {
  margin: 0;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.01em;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
  white-space: nowrap;
}

.pet-card {
  flex: 1;
  max-width: 300px;
  padding: 8px 14px 10px;
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
}

.pet-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  font-weight: 800;
}

.pet-name {
  font-size: 17px;
}

.pet-stage,
.pet-level {
  font-size: 11px;
  font-weight: 800;
  padding: 3px 8px;
  border-radius: 999px;
  background: #ffe3ee;
  color: #b4467a;
}

.pet-level {
  margin-left: auto;
  background: #fff1cf;
  color: #9a6510;
  white-space: nowrap;
}

.xp-track {
  margin-top: 8px;
  height: 7px;
  border-radius: 999px;
  background: rgba(120, 90, 140, 0.14);
  overflow: hidden;
}

.xp-fill {
  height: 100%;
  width: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--accent-2), var(--accent));
  transform-origin: left center;
  transform: scaleX(0);
  transition: transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.top-tools {
  display: flex;
  flex-shrink: 0;
  gap: 8px;
}

.icon-btn {
  width: 40px;
  height: 40px;
  border: none;
  border-radius: 14px;
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.12);
  font-size: 18px;
  line-height: 1;
}

.icon-btn:hover {
  transform: translateY(-1px);
}

/* ---------- Stage ---------- */

.stage {
  position: relative;
  min-height: 0;
  overflow: hidden;
  background: linear-gradient(180deg, #8fd3ff 0%, #c9ecff 45%, #fff3d6 100%);
  transition: background 1.2s ease;
}

.stage.night {
  background: linear-gradient(180deg, #1c2050 0%, #35407a 55%, #7a6fa8 100%);
}

.stage.asleep::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(20, 16, 50, 0.32);
  pointer-events: none;
  animation: fade-in 1.2s ease both;
}

.stage.feed-target {
  box-shadow: inset 0 0 90px rgba(255, 214, 120, 0.7);
}

.stage.dragging {
  cursor: grabbing;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: manipulation;
  cursor: pointer;
}

.bubble {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 2;
  max-width: 230px;
  padding: 9px 14px;
  border-radius: 18px;
  background: #fff;
  color: var(--ink);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 10px 26px rgba(60, 40, 90, 0.18);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  margin-top: -16px;
}

.bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 3px;
}

.bubble.show {
  opacity: 1;
}

.zzz {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 2;
  display: flex;
  gap: 4px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 2px 6px rgba(20, 16, 60, 0.4);
}

.zzz.show {
  opacity: 1;
}

.zzz span {
  animation: zzz-float 2.4s ease-in-out infinite;
  font-size: 14px;
}

.zzz span:nth-child(2) {
  animation-delay: 0.6s;
  font-size: 18px;
}

.zzz span:nth-child(3) {
  animation-delay: 1.2s;
  font-size: 22px;
}

.float-emoji {
  position: absolute;
  z-index: 3;
  font-size: 26px;
  pointer-events: none;
  transform: translate(-50%, -50%);
  animation: float-up 1.1s ease-out forwards;
}

.hint {
  position: absolute;
  left: 50%;
  bottom: 14px;
  z-index: 2;
  transform: translateX(-50%);
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.8);
  font-size: 13px;
  font-weight: 700;
  color: var(--ink-soft);
  white-space: nowrap;
  pointer-events: none;
  transition: opacity 0.6s ease;
}

.hint.gone {
  opacity: 0;
}

.toast {
  position: fixed;
  top: 84px;
  left: 50%;
  z-index: 10;
  transform: translate(-50%, -8px);
  padding: 10px 16px;
  border-radius: 999px;
  background: #2d2a4a;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 10px 26px rgba(30, 20, 60, 0.3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Meters ---------- */

.meters {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 10px 14px 8px;
  position: relative;
  z-index: 3;
}

.meter {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 6px;
  row-gap: 4px;
  padding: 8px 10px;
  border-radius: 16px;
  background: var(--card);
  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.1);
}

.meter-icon {
  font-size: 14px;
  line-height: 1;
}

.meter-label {
  font-size: 12px;
  font-weight: 800;
  color: var(--ink-soft);
  white-space: nowrap;
}

.meter-value {
  grid-column: 2;
  justify-self: end;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
  margin-top: -2px;
}

.meter-track {
  grid-column: 1 / -1;
  height: 8px;
  border-radius: 999px;
  background: rgba(120, 90, 140, 0.14);
  overflow: hidden;
}

.meter-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffd166, #ff8fb1);
  transform-origin: left center;
  transform: scaleX(0.5);
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.3s ease;
}

.meter[data-stat="energy"] .meter-fill {
  background: linear-gradient(90deg, #9ee8ff, #7aa8ff);
}

.meter[data-stat="hygiene"] .meter-fill {
  background: linear-gradient(90deg, #b8f2d0, #6fd3a6);
}

.meter[data-low="true"] .meter-fill {
  background: linear-gradient(90deg, #ffb199, #ff6f7c);
  animation: pulse 1.2s ease-in-out infinite;
}

/* ---------- Dock ---------- */

.dock {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 4px 12px 16px;
}

.dock-row {
  display: flex;
  gap: 10px;
  justify-content: center;
}

.dock-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  width: 78px;
  padding: 9px 6px 8px;
  border: none;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 8px 20px rgba(80, 60, 120, 0.14);
  font-size: 12px;
  font-weight: 800;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.dock-btn:hover {
  transform: translateY(-2px);
}

.dock-btn:active {
  transform: scale(0.95);
}

.dock-btn.active {
  background: #fff4f8;
  box-shadow: 0 0 0 3px var(--accent), 0 8px 20px rgba(80, 60, 120, 0.14);
}

.dock-emoji {
  font-size: 22px;
  line-height: 1.1;
}

.food-tray {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 100%;
  z-index: 4;
  margin: 0 auto 8px;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  width: min(560px, calc(100% - 24px));
  padding: 10px;
  border-radius: 22px;
  background: var(--card);
  box-shadow: 0 12px 30px rgba(80, 60, 120, 0.18);
  animation: rise 0.25s ease both;
}

.food-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 8px 4px 7px;
  border: 2px solid transparent;
  border-radius: 16px;
  background: #fff;
  cursor: grab;
  touch-action: none;
  transition: transform 0.15s ease, border-color 0.2s ease;
}

.food-card:hover {
  transform: translateY(-2px);
  border-color: var(--food);
}

.food-card:active {
  cursor: grabbing;
}

.food-card.locked {
  cursor: not-allowed;
  opacity: 0.55;
  filter: grayscale(0.7);
}

.food-emoji {
  font-size: 28px;
  line-height: 1.1;
}

.food-name {
  font-size: 12px;
  font-weight: 800;
}

.food-blurb {
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-soft);
  text-align: center;
  line-height: 1.2;
}

/* ---------- Motion ---------- */

@keyframes float-up {
  0% {
    opacity: 0;
    transform: translate(-50%, -30%) scale(0.6);
  }
  20% {
    opacity: 1;
    transform: translate(-50%, -60%) scale(1.1);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--drift, 0px)), -220%) scale(0.9);
  }
}

@keyframes zzz-float {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.6;
  }
  50% {
    transform: translateY(-8px);
    opacity: 1;
  }
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* ---------- Small screens ---------- */

@media (max-width: 520px) {
  .hud-top {
    padding: 10px 10px 4px;
    gap: 8px;
  }

  .brand h1 {
    font-size: 11px;
    padding: 6px 9px;
  }

  .pet-card {
    flex: 1;
    min-width: 0;
    max-width: none;
    padding: 6px 10px 8px;
  }

  .pet-name {
    font-size: 15px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .pet-stage,
  .pet-level {
    font-size: 10px;
  }

  .icon-btn {
    width: 36px;
    height: 36px;
  }

  .meters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 8px 10px 6px;
  }

  .hint {
    max-width: calc(100% - 28px);
    white-space: normal;
    text-align: center;
  }

  .dock {
    padding: 4px 8px 14px;
  }

  .food-tray {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: calc(100% - 20px);
    padding: 8px;
  }

  .food-blurb {
    display: none;
  }

  .dock-btn {
    width: 68px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

