  box-shadow: 0 6px 18px rgba(80, 60, 120, 0.1);
}

.meter-icon {
  font-size: 14px;
  line-height: 1;
}

.meter-label {
  font-size: 12px;
  font-weight: 800;
  color: var(--ink-soft);
  white-space: nowrap;
}

.meter-value {
  grid-column: 2;
  justify-self: end;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink-soft);
  margin-top: -2px;
}

.meter-track {
  grid-column: 1 / -1;
  height: 8px;
  border-radius: 999px;
  background: rgba(120, 90, 140, 0.14);
  overflow: hidden;
}

.meter-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffd166, #ff8fb1);
  transform-origin: left center;
  transform: scaleX(0.5);
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.3s ease;
}

.meter[data-stat="energy"] .meter-fill {
  background: linear-gradient(90deg, #9ee8ff, #7aa8ff);
}

.meter[data-stat="hygiene"] .meter-fill {
  background: linear-gradient(90deg, #b8f2d0, #6fd3a6);
}

.meter[data-low="true"] .meter-fill {
  background: linear-gradient(90deg, #ffb199, #ff6f7c);
  animation: pulse 1.2s ease-in-out infinite;
}

/* ---------- Dock ---------- */

.dock {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 4px 12px 16px;
}

.dock-row {
  display: flex;
  gap: 10px;
  justify-content: center;
}

.dock-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  width: 78px;
  padding: 9px 6px 8px;
  border: none;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 8px 20px rgba(80, 60, 120, 0.14);
  font-size: 12px;
  font-weight: 800;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.dock-btn:hover {
  transform: translateY(-2px);
}

.dock-btn:active {
  transform: scale(0.95);
}

.dock-btn.active {
  background: #fff4f8;
  box-shadow: 0 0 0 3px var(--accent), 0 8px 20px rgba(80, 60, 120, 0.14);
}

.dock-emoji {
  font-size: 22px;
  line-height: 1.1;
}

.food-tray {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 100%;
  z-index: 4;
  margin: 0 auto 8px;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  width: min(560px, calc(100% - 24px));
  padding: 10px;
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 12px 30px rgba(80, 60, 120, 0.18);
  animation: rise 0.25s ease both;
}

.food-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 8px 4px 7px;
  border: 2px solid transparent;
  border-radius: 16px;
  background: #fff;
  cursor: grab;
  touch-action: none;
  transition: transform 0.15s ease, border-color 0.2s ease;
}

.food-card:hover {
  transform: translateY(-2px);
  border-color: var(--food);
}

.food-card:active {
  cursor: grabbing;
}

.food-card.locked {
  cursor: not-allowed;
  opacity: 0.55;
  filter: grayscale(0.7);
}

.food-emoji {
  font-size: 28px;
  line-height: 1.1;
}

.food-name {
  font-size: 12px;
  font-weight: 800;
}

.food-blurb {
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-soft);
  text-align: center;
  line-height: 1.2;
}

/* ---------- Motion ---------- */

@keyframes float-up {
  0% {
    opacity: 0;
    transform: translate(-50%, -30%) scale(0.6);
  }
  20% {
    opacity: 1;
    transform: translate(-50%, -60%) scale(1.1);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--drift, 0px)), -220%) scale(0.9);
  }
}

@keyframes zzz-float {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.6;
  }
  50% {
    transform: translateY(-8px);
    opacity: 1;
  }
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* ---------- Small screens ---------- */

@media (max-width: 520px) {
  .hud-top {
    padding: 10px 10px 4px;
    gap: 8px;
  }

  .brand h1 {
    font-size: 11px;
    padding: 6px 9px;
  }

  .pet-card {
    flex: 1;
    min-width: 0;
    max-width: none;
    padding: 6px 10px 8px;
  }

  .pet-name {
    font-size: 15px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .pet-stage,
  .pet-level {
    font-size: 10px;
  }

  .icon-btn {
    width: 36px;
    height: 36px;
  }

  .meters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 8px 10px 6px;
  }

  .hint {
    max-width: calc(100% - 28px);
    white-space: normal;
    text-align: center;
  }

  .dock {
    padding: 4px 8px 14px;
  }

  .food-tray {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: calc(100% - 20px);
    padding: 8px;
  }

  .food-blurb {
    display: none;
  }

  .dock-btn {
    width: 68px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

